import unicodedata, pathlib
p = pathlib.Path('/tmp/orchestra-07/out/baseline-ts001.md')
text = p.read_text()
hits = []
for i, line in enumerate(text.splitlines(), 1):
    for ch in line:
        if ord(ch) < 128:
            continue
        cat = unicodedata.category(ch)
        if cat.startswith('P') or cat == 'Sm':
            hits.append((i, ch, unicodedata.name(ch, '?')))
for h in hits[:50]:
    print(h)
print('total hits:', len(hits))
